def parse_endpoint_or_none(value):
    # ey 的 base/target：null 表示未登记端点，否则为精确键序 host,port 的
    # 对象，校验沿用 ep（规范化 IP 字面量与 1..65535 非 bool 端口）。
    if value is None:
