class EpSwitchConditionalReplaceTest(unittest.TestCase):
    """eo：全池端点切换预约条件替换——旧身份替换、新身份幂等重报、
    INPUT/BACKEND/STATE 优先级、凭据轮换、副作用边界、检查点与
    record/replay 逐字节契约。"""

